const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const newYork = ee.Geometry.Point([-74.0060, 40.7128]); // New York City
    const startDate2016 = '2016-07-17'; // MODIS 8-day composite usually starts around this date for July 20-27
    const endDate2016 = '2016-07-24'; // End of the 8-day composite period

    const startYearAvg = 2001;
    const endYearAvg = 2010;
    const dayOfYearStart = ee.Date(startDate2016).getRelative('day', 'year').add(1); // Day of year for July 17th
    const dayOfYearEnd = ee.Date(endDate2016).getRelative('day', 'year').add(1); // Day of year for July 24th

    // 2. Data Acquisition & Preprocessing
    const collection = ee.ImageCollection('MODIS/051/MOD11A2');

    // Function to mask clouds and scale LST_Day_1km to Celsius
    function preprocessModisLST(image) {
      // Bits 0-1 are quality flags. 00 (0) = good quality, 01 (1) = low quality, 10 (2) = cloud, 11 (3) = cloud
      // We want pixels with good quality (00).
      const qc = image.select('QC_Day');
      const goodQuality = qc.bitwiseAnd(3).eq(0); // Check if bits 0 and 1 are 00

      // Select LST_Day_1km, scale by 0.02, and convert to Celsius (subtract 273.15)
      const lst = image.select('LST_Day_1km')
        .multiply(0.02)
        .subtract(273.15)
        .updateMask(goodQuality); // Apply the quality mask
      return lst.rename('LST_Day_1km').copyProperties(image, ['system:time_start']);
    }

    // Filter for 2016 data
    const col2016 = collection
      .filterDate(startDate2016, ee.Date(endDate2016).advance(1, 'day'))
      .filterBounds(newYork);

    if (col2016.size().getInfo() === 0) {
      console.log("No images found for 2016 in the specified period/location.");
      console.log("C1");
      return;
    }

    const image2016 = col2016.first();
    const processedImage2016 = preprocessModisLST(image2016);

    // Filter for historical average data (2001-2010)
    let historicalImages = ee.ImageCollection([]);
    for (let year = startYearAvg; year <= endYearAvg; year++) {
      const yearStart = ee.Date.fromYMD(year, 1, 1).advance(dayOfYearStart.subtract(1), 'day');
      const yearEnd = ee.Date.fromYMD(year, 1, 1).advance(dayOfYearEnd.subtract(1), 'day');

      const yearCol = collection
        .filterDate(yearStart, yearEnd.advance(1, 'day')) // Filter for the specific 8-day period
        .filterBounds(newYork);

      // Take the first image of the period, if multiple exist (should be 1 for 8-day composite)
      if (yearCol.size().getInfo() > 0) {
        historicalImages = historicalImages.merge(yearCol.first());
      }
    }

    if (historicalImages.size().getInfo() === 0) {
      console.log("No images found for the 2001-2010 average period.");
      console.log("C1");
      return;
    }

    const processedHistoricalImages = historicalImages.map(preprocessModisLST);
    const avgHistoricalLST = processedHistoricalImages.mean();

    // 3. Calculation and Validation
    const scale = 1000; // MODIS LST resolution is 1km

    // Reduce region for 2016 LST
    const result2016 = processedImage2016.reduceRegion({
      reducer: ee.Reducer.mean().setOutputs(['LST_Day_1km']).count().setOutputs(['count']),
      geometry: newYork,
      scale: scale,
      maxPixels: 1e9
    });

    const lst2016 = result2016.get('LST_Day_1km').getInfo();
    const count2016 = result2016.get('count').getInfo();

    // Reduce region for average historical LST
    const resultAvg = avgHistoricalLST.reduceRegion({
      reducer: ee.Reducer.mean().setOutputs(['LST_Day_1km']).count().setOutputs(['count']),
      geometry: newYork,
      scale: scale,
      maxPixels: 1e9
    });

    const lstAvg = resultAvg.get('LST_Day_1km').getInfo();
    const countAvg = resultAvg.get('count').getInfo();

    if (count2016 === 0 || countAvg === 0) {
      console.log(`2016 Pixels: ${count2016}, Avg Pixels: ${countAvg}`);
      console.log("No valid pixels remaining after cloud masking for one or both periods.");
      console.log("C2");
      return;
    }

    if (lst2016 === null || lstAvg === null || isNaN(lst2016) || isNaN(lstAvg)) {
      console.log(`2016 LST: ${lst2016}, Avg LST: ${lstAvg}`);
      console.log("Calculation resulted in Null/NaN for LST.");
      console.log("C3");
      return;
    }

    // 5. Validation & Final Answer
    console.log(`2016 LST (C): ${lst2016.toFixed(2)} (Pixels: ${count2016})`);
    console.log(`2001-2010 Avg LST (C): ${lstAvg.toFixed(2)} (Pixels: ${countAvg})`);

    if (lst2016 > lstAvg) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.log("D");
    console.error("Analysis error: ", error);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
